import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CyZTVJbV.js";const v=JSON.parse('{"title":"kiwa v1.45 リリース — Realtime III 深化 milestone + 縦深化 pair 第 2 pair 3 段拡張達成 (3 例目 record)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.45/zenn-article.md","filePath":"announcements/v1.45/zenn-article.md"}'),d={name:"announcements/v1.45/zenn-article.md"};function o(n,t,s,l,c,p){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="kiwa-v1-45-リリース-—-realtime-iii-深化-milestone-縦深化-pair-第-2-pair-3-段拡張達成-3-例目-record" tabindex="-1">kiwa v1.45 リリース — Realtime III 深化 milestone + 縦深化 pair 第 2 pair 3 段拡張達成 (3 例目 record) <a class="header-anchor" href="#kiwa-v1-45-リリース-—-realtime-iii-深化-milestone-縦深化-pair-第-2-pair-3-段拡張達成-3-例目-record" aria-label="Permalink to &quot;kiwa v1.45 リリース — Realtime III 深化 milestone + 縦深化 pair 第 2 pair 3 段拡張達成 (3 例目 record)&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>kiwa v1.45 をリリースしました。 <strong>縦深化 pair 第 2 pair (Realtime) 3 段拡張達成</strong> — v1.13 v0.1 (base) → v1.28 v0.2 (WebRTC / WebTransport / HTTP/3 / QUIC) → v1.45 v0.3 (MoQ / WebCodecs / AI-media) の 3 段構造、 pair 第 8 Search + pair 第 1 Auth に続く <strong>3 例目 pair 深度 3 段記録</strong>。</p><h2 id="何が変わったか" tabindex="-1">何が変わったか <a class="header-anchor" href="#何が変わったか" aria-label="Permalink to &quot;何が変わったか&quot;">​</a></h2><h3 id="kiwa-lab-realtime-v0-3-0-v0-2-0-→-v0-3-0-minor-bump" tabindex="-1"><code>@kiwa-lab/realtime</code> v0.3.0 (v0.2.0 → v0.3.0 minor bump) <a class="header-anchor" href="#kiwa-lab-realtime-v0-3-0-v0-2-0-→-v0-3-0-minor-bump" aria-label="Permalink to &quot;`@kiwa-lab/realtime` v0.3.0 (v0.2.0 → v0.3.0 minor bump)&quot;">​</a></h3><p>8 個の advanced III axis を追加しました。</p><ul><li><strong>moq-fetch</strong> — MoQT (draft-ietf-moq-transport) track announce + subscribe + object delivery</li><li><strong>moq-datagram-media</strong> — partial reliability + Forward Error Correction (FEC) recovery + priority</li><li><strong>webcodecs-encoder</strong> — VideoEncoder / AudioEncoder direct API + hardware acceleration hints</li><li><strong>webcodecs-decoder</strong> — reorder buffer + drop policy + key/delta frame handling</li><li><strong>simulcast-svc</strong> — Simulcast + Scalable Video Coding (L1T1 → L3T3) + adaptive bitrate</li><li><strong>voice-streaming</strong> — LLM voice streaming (OpenAI Realtime API + Anthropic voice)</li><li><strong>whisper-streaming</strong> — Whisper streaming ASR + partial transcript + Voice Activity Detection</li><li><strong>realtime-ai-inference</strong> — per-frame prediction + latency budget enforcement</li></ul><p>3 新 protocol (MoQ / WebCodecs / AI-media) 追加。</p><h3 id="_3-dogfood-app-を新規追加" tabindex="-1">3 dogfood app を新規追加 <a class="header-anchor" href="#_3-dogfood-app-を新規追加" aria-label="Permalink to &quot;3 dogfood app を新規追加&quot;">​</a></h3><ul><li><code>dogfood-realtime-moq-webcodecs-app</code> — 60 tests。 MoQ + WebCodecs encoder + Simulcast/SVC。</li><li><code>dogfood-realtime-voice-streaming-app</code> — 60 tests。 voice + Whisper + AI inference。</li><li><code>dogfood-realtime-svc-adaptive-app</code> — 60 tests。 SVC + WebCodecs decoder + MoQ datagram。</li></ul><h3 id="_3-tutorial-を新規追加" tabindex="-1">3 tutorial を新規追加 <a class="header-anchor" href="#_3-tutorial-を新規追加" aria-label="Permalink to &quot;3 tutorial を新規追加&quot;">​</a></h3><ul><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/100-moq-webcodecs" target="_blank" rel="noreferrer">Tutorial 100 — MoQ + WebCodecs</a></strong></li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/101-voice-streaming" target="_blank" rel="noreferrer">Tutorial 101 — Voice streaming</a></strong></li><li><strong><a href="https://cardene777.github.io/kiwa/tutorials/102-svc-adaptive" target="_blank" rel="noreferrer">Tutorial 102 — SVC adaptive</a></strong></li></ul><h2 id="_23-milestone-連続-snippet-validation-streak-達成" tabindex="-1">23 milestone 連続 snippet validation streak 達成 <a class="header-anchor" href="#_23-milestone-連続-snippet-validation-streak-達成" aria-label="Permalink to &quot;23 milestone 連続 snippet validation streak 達成&quot;">​</a></h2><p>v1.23 → v1.45 で 23 milestone 連続。</p><h2 id="縦深化-pair-pattern-grid" tabindex="-1">縦深化 pair pattern grid <a class="header-anchor" href="#縦深化-pair-pattern-grid" aria-label="Permalink to &quot;縦深化 pair pattern grid&quot;">​</a></h2><p>12 pair が記録されています。 <strong>Pair 1 + Pair 2 + Pair 8 が深度 3</strong>。</p><table tabindex="0"><thead><tr><th>Pair</th><th>Domain</th><th>Path</th><th>Depth</th></tr></thead><tbody><tr><td>1</td><td>Auth</td><td>v1.21→v1.22→v1.44</td><td>3</td></tr><tr><td><strong>2</strong></td><td><strong>Realtime</strong></td><td><strong>v1.13→v1.28→v1.45</strong></td><td><strong>3</strong></td></tr><tr><td>3</td><td>Streaming</td><td>v1.20→v1.31</td><td>2</td></tr><tr><td>4</td><td>Database</td><td>v1.14→v1.32</td><td>2</td></tr><tr><td>5</td><td>Payment</td><td>v1.14→v1.19→v1.33→v1.41</td><td>4</td></tr><tr><td>6</td><td>Frontend</td><td>v1.16→v1.34</td><td>2</td></tr><tr><td>7</td><td>Observability</td><td>v1.14→v1.17→v1.35→v1.42</td><td>4</td></tr><tr><td>8</td><td>Search</td><td>v1.14→v1.15→v1.36</td><td>3</td></tr><tr><td>9</td><td>Security</td><td>v1.37→v1.39</td><td>2</td></tr><tr><td>10</td><td>AI/LLM</td><td>v1.12→v1.15→v1.38→v1.40</td><td>4</td></tr><tr><td>11</td><td>Security base</td><td>v1.37</td><td>1</td></tr><tr><td>12</td><td>Edge / Serverless</td><td>v1.43</td><td>1</td></tr></tbody></table><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/realtime@^0.3</span></span></code></pre></div><h2 id="migration-guide" tabindex="-1">Migration guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration guide&quot;">​</a></h2><p><a href="https://cardene777.github.io/kiwa/migrations/v1.44-to-v1.45" target="_blank" rel="noreferrer">v1.44 → v1.45 migration guide</a></p><h2 id="次に何が来るか" tabindex="-1">次に何が来るか <a class="header-anchor" href="#次に何が来るか" aria-label="Permalink to &quot;次に何が来るか&quot;">​</a></h2><p>v1.45 で 3 例目 pair 深度 3 段記録達成、 5-milestone new-base cadence + 中間 milestone での既存 pair 深化 の 2 段組み rhythm 定着継続。 次候補 = Streaming III / Database III / Frontend III / Security III (残 4 pair-2 candidate)。 次回 new base = v1.48 前後。</p>',23)])])}const m=e(d,[["render",o]]);export{v as __pageData,m as default};
